        in.nextToken();
        int n = (int) in.nval;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            in.nextToken();
            sb.append(parity((long) in.nval)).append("\n");
        }
        System.out.print(sb);
