            tests.append(fmt([rng.randint(-r, r) for _ in range(n)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(100000)]))
    tests.append(fmt([2 * rng.randint(-5 * 10**8, 5 * 10**8) for _ in range(100000)]))
    tests.append(fmt([(-1) ** i * (10**9 - i) for i in range(100000)]))
